# Let's find all rectangles defined by 1-borders in the input demo
def find_1_rectangles(grid):
    """Find rectangular regions where the border is made of 1s"""
    rows = len(grid)
    cols = len(grid[0])
    rects = []

    # Try each possible top-left corner
    for r1 in range(rows):
        for c1 in range(cols):
            if grid[r1][c1] != 1:
                continue

            # Find bottom-right corner
            for r2 in range(r1 + 1, rows):
                for c2 in range(c1 + 1, cols):
                    # Check if this forms a valid rectangle with 1 border
                    # Top row (r1): columns c1 to c2 should all be 1
                    if any(grid[r1][c] != 1 for c in range(c1, c2+1)):
                        continue

                    # Bottom row (r2): columns c1 to c2 should all be 1
                    if any(grid[r2][c] != 1 for c in range(c1, c2+1)):
                        continue

                    # Left column: rows r1 to r2 should all be 1
                    if any(grid[r][c1] != 1 for r in range(r1, r2+1)):
                        continue

                    # Right column: rows r1 to r2 should all be 1
                    if any(grid[r][c2] != 1 for r in range(r1, r2+1)):
                        continue

                    rects.append(((r1, c1), (r2, c2)))

    return rects

