# and find the minimal rectangles that cover all changed cells

def find_filled_rectangles(input_grid, output_grid):
    """Find rectangular regions that were filled (changed to some common value)"""
    rows = len(input_grid)
    cols = len(input_grid[0])

    # Find all changed cells
    changes = set()
    for r in range(rows):
        for c in range(cols):
            if input_grid[r][c] != output_grid[r][c]:
                changes.add((r, c))

    if not changes:
        return []

    # Group changes into rectangles
    # For each change, determine which other changes form a rectangle with it
    rects = []
    processed = set()

    for r1, c1 in sorted(changes):
        if (r1, c1) in processed:
            continue

        # Try to find a rectangle containing this cell as top-left
        r_max, c_max = r1, c1

        # Extend as far as possible while maintaining rectangular structure
        for r in range(r1, rows):
            for c in range(c1, cols):
                if (r, c) not in changes:
                    # Check if including this would still make sense
                    pass

                # Mark as potentially part of this rectangle
                r_max = max(r_max, r)
                c_max = max(c_max, c)

        # Now verify if the region [r1:r_max+1, c1:c_max+1] consists only of changed cells
        rect_cells = [(r, c) for r in range(r1, r_max + 1) for c in range(c1, c_max + 1)]
        if all(cell in changes for cell in rect_cells):
            rects.append(((r1, c1), (r_max, c_max)))
            for r in range(r1, r_max + 1):
                for c in range(c1, c_max + 1):
                    processed.add((r, c))

    return rects

